"""Compile Section-end bindings for native, once-owned curved carriageways.

Only input records and source lookup indices are constructed here. Geometry
Nodes determines both mouth trims, rounds bends and builds every surface.
"""
import math
import bpy
from mathutils import Matrix
from . import model, runtime, live_bindings


def _attribute(mesh, name, kind, values):
    attr=mesh.attributes.new(name,kind,'POINT')
    attr.data.foreach_set('value',values)


def _junctions(net):
    old,_=runtime.solver_modules()
    sections={s.id:s for s in net.canonical.sections}
    owners=net.canonical.section_streets()
    datums={round(j.datum,7) for j in net.intersection_records.values()}
    if len(datums)!=1:raise ValueError('Linked paths currently require one common flat datum')
    if net.bundle_records:raise ValueError('Divided linked paths require a later shared-envelope sweep')
    attached={};result=[];ends={}
    for j in net.intersection_records.values():
        connectors=[c for c in net.connector_records.values() if c.intersection_id==j.id]
        if len(connectors)<3:raise ValueError('Each local intersection requires at least three connectors')
        def angle(c):
            sid,end=c.members[0];p=sections[sid].vertices
            a,b=(p[0],p[1]) if end==0 else (p[-1],p[-2])
            return math.atan2(b[1]-a[1],b[0]-a[0])%math.tau
        connectors.sort(key=angle)
        streets=[];inputs=[];profiles=[]
        for i,c in enumerate(connectors):
            if len(c.members)!=1 or c.separator:raise ValueError('Linked paths initially use single carriageway connectors')
            sid,end=c.members[0];section=sections[sid];profile=net.section_records[sid]
            if (sid,end) in attached:raise ValueError('A Section end has two intersection owners')
            attached[sid,end]=j.id;ends[j.id,sid]=end
            if c.use_profile_override and (c.rise!=profile.rise or c.preset!=profile.preset):
                raise ValueError('Linked carriageway must keep the same profile at both mouths')
            points=section.vertices[:2] if end==0 else section.vertices[-2:]
            streets.append(old.StreetInput(owners[sid],(old.SectionInput(sid,points,section.width,section.offset),)))
            profiles.append(old.ProfileInput(profile.rise,old.FLAT if profile.preset=='FLAT' else old.SMOOTH_CROWN))
            radius=c.radius_override if c.radius_override>0 else j.radius
            if c.radius_override>0 and c.radius_next_connector_id!=connectors[(i+1)%len(connectors)].id:
                raise ValueError('Corner override no longer identifies an adjacent connector pair')
            inputs.append(old.ConnectorInput(c.id,(old.MemberInput(i,end==0),),i,radius=radius))
        junction=old.PreparedJunction(j.id,j.position,tuple(streets),tuple(inputs),tuple(profiles),j.datum,net.cell_size)
        old.validate_initial_scope(junction);result.append(junction)
    if not result:raise ValueError('A linked network needs intersections')
    return tuple(result),ends,attached


def _bind_rays(mesh,junction,sections,ends=None,*,incidence_ends=None):
    """Bind each local incidence to its original authored terminal edge.

    Returning Sections require distinct start/end bindings at one junction.
    incidence_ends addresses the local Street row, not just the source Section.
    The older Section-keyed map remains supported for existing callers.
    """
    vp_rows=[];ep_rows=[];endpoint_keys=[];section_ids=[];end_codes=[]
    for index,street in enumerate(junction.streets):
        sid=street.sections[0].source_id
        end=(incidence_ends[junction.source_id,index] if incidence_ends is not None
             else ends[junction.source_id,sid])
        vp,ep=sections[sid]
        pair=vp[:2] if end==0 else vp[-2:]
        edge=ep[0] if end==0 else ep[-1]
        for i,key in enumerate(pair):
            role=1 if key==vp[0] else 2 if key==vp[-1] else 0
            vp_rows.append((key,pair[0],pair[-1],pair[-1],role))
        ep_rows.append((edge,edge,sid,*pair))
        endpoint_keys.append(vp[0] if end==0 else vp[-1]);section_ids.append(sid);end_codes.append(end)
    n=len(mesh.vertices)
    for k,name in enumerate(('st_live_vertex_index','st_live_start_index','st_live_end_index','st_live_next_index','st_live_endpoint_role')):
        live_bindings.attribute(mesh,name,'POINT',[v[k] for v in vp_rows]+[-1]*(n-len(vp_rows)))
    for k,name in enumerate(('st_live_edge_index','st_live_first_edge_index','st_live_section_id','st_live_v0','st_live_v1')):
        live_bindings.attribute(mesh,name,'EDGE',[e[k] for e in ep_rows])
    for name in ('st_live_seam_index','st_live_seam_neighbor_index','st_live_own_neighbor_index','st_live_seam_edge_index','st_live_own_edge_index','st_live_seam_offset_sign','st_live_required_nv'):
        live_bindings.attribute(mesh,name,'POINT',[-1]*n)
    tags=mesh.attributes['s2_record_type'];member_indices=[i for i,d in enumerate(tags.data) if d.value==5]
    for name,values in [('st_path_endpoint',endpoint_keys),('st_path_section_id',section_ids),('st_path_end',end_codes),
                        ('st_path_start',[sections[sid][0][0] for sid in section_ids]),
                        ('st_path_count',[len(sections[sid][0]) for sid in section_ids])]:
        all_values=[-1]*n
        # MEMBER rows follow cyclic connector order, which need not match the
        # STREET table (and paired connectors contribute two adjacent members).
        # Each record already explicitly identifies its Street table row.
        for i in member_indices:
            street_index=mesh.attributes['s2_street_index'].data[i].value
            all_values[i]=values[street_index]
        live_bindings.attribute(mesh,name,'POINT',all_values)
    mesh.update()


def _path_object(controller,net,sections,attached):
    name='Prochitecture Streets / Path records / '+controller.st_network.network_uuid
    obj=bpy.data.objects.get(name)
    mesh=bpy.data.meshes.new(name+' data')
    ordered=sorted(net.section_records);mesh.from_pydata([(0.,0.,0.)]*len(ordered),[],[])
    datum=next(iter(net.intersection_records.values())).datum
    fields={key:[] for key in ('st_path_id','st_path_start','st_path_count','st_path_edge','st_path_attached_start','st_path_attached_end','st_path_rise','st_path_datum')}
    for sid in ordered:
        vp,ep=sections[sid]
        values=(sid,vp[0],len(vp),ep[0],(sid,0) in attached,(sid,1) in attached,net.section_records[sid].rise,datum)
        for key,value in zip(fields,values):fields[key].append(value)
    for key,values in fields.items():
        kind='BOOLEAN' if 'attached' in key else 'FLOAT' if key in ('st_path_rise','st_path_datum') else 'INT'
        _attribute(mesh,key,kind,values)
    if obj is None:
        obj=bpy.data.objects.new(name,mesh);bpy.context.scene.collection.objects.link(obj)
    else:
        previous=obj.data;obj.data=mesh
        if previous.users==0:bpy.data.meshes.remove(previous)
    obj.matrix_world=Matrix.Identity(4);obj.hide_render=True;obj.hide_select=True;obj.hide_set(True)
    obj.st_generated_controller=controller
    return obj


def refresh(controller, *, force=False, raise_errors=False):
    from . import path_network_nodes
    if not controller.get('st_connected_paths',False):
        changed=runtime.refresh(controller,force=force,raise_errors=raise_errors,_legacy=True)
        if changed:
            mod=next(m for m in controller.modifiers if m.type=='NODES')
            values={s.name:getattr(mod.properties.inputs,s.identifier).value for s in mod.node_group.interface.items_tree
                    if s.item_type=='SOCKET' and s.in_out=='INPUT' and s.name!='Geometry'}
            mod.node_group=path_network_nodes.build(runtime.ensure_kernel())
            for key,value in values.items():runtime._set_modifier(controller,key,value)
        return changed
    if runtime._busy:return False
    try:
        with runtime.suspend():
            bpy.context.view_layer.update();net=model.read_network(controller)
            signature=(net.signature,tuple((sid,s.object.as_pointer(),s.object.data.as_pointer(),s.vertex_indices,s.edge_indices)
                       for sid,s in sorted(net.section_sources.items())))
            key=controller.as_pointer()
            if not force and runtime._last.get(key)==signature:return False
            junctions,ends,attached=_junctions(net)
            source_collection,sections,_seams,nv,ne=live_bindings.compile_sources(controller,net)
            collection=runtime._cache_collection(controller)
            carriers=tuple(runtime._carrier(controller,j,collection) for j in junctions)
            for obj,j in zip(carriers,junctions):_bind_rays(obj.data,j,sections,ends)
            runtime._synchronize_carriers(controller,collection,carriers)
            paths=_path_object(controller,net,sections,attached)
            group=path_network_nodes.build(runtime.ensure_kernel())
            mod=next((m for m in controller.modifiers if m.type=='NODES'),None) or controller.modifiers.new('Editable Street network','NODES')
            mod.node_group=group
            values={'Source Objects':source_collection,'Source Vertex Count':nv,'Source Edge Count':ne,
                    'Junction Inputs':collection,'Path Inputs':paths,'Linked Paths':True,'Cell Size':net.cell_size,
                    'Metres to Blender Units':1/net.scale_length,'Mesh Resolution':controller.st_network.resolution,
                    'Height Exaggeration':controller.st_network.exaggeration,'Enabled':True}
            for material in ('Pavement','Grass'):
                mat=bpy.data.materials.get('Prochitecture Streets / '+material)
                if mat:values[material]=mat
            for name,value in values.items():runtime._set_modifier(controller,name,value)
            controller.update_tag();bpy.context.view_layer.update()
            ev=controller.evaluated_get(bpy.context.evaluated_depsgraph_get());mesh=ev.to_mesh()
            try:
                if not mesh.polygons:raise ValueError('GN rejected linked network: inspect endpoint lengths, bends, widths and mouth trims')
            finally:ev.to_mesh_clear()
            runtime._last[key]=signature
            runtime._set_status(controller,'READY','Native Section links: once-owned carriageways and independently trimmed intersections')
            return True
    except Exception as exc:
        runtime._last.pop(controller.as_pointer(),None)
        if controller.modifiers:runtime._set_modifier(controller,'Enabled',False)
        runtime._set_status(controller,'INVALID',str(exc))
        if raise_errors:raise
        return False
